-- ===== U6 vocab 覆盖灌库(volume='9',55词)。分步跑,每步贴回 count。=====

-- [step0] 灌前 count
SELECT 'U6 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U6';

-- [step1] DELETE 旧骨架(键 grade=9 volume='9' unit='U6')
DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U6';
SELECT 'U6 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U6';  -- 应0

-- [step2] INSERT 官方 55 词(volume='9' + WHERE NOT EXISTS 防重)
-- [step2 验证] 预期 55
SELECT 'U6 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U6';

-- ===== 末尾查重(预期 0 行) =====
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U6' GROUP BY word HAVING count(*)>1;